def can_chain(dominoes):
    """Return a valid circular domino chain using every stone, or None."""
    if not dominoes:
        return []

    # Each stone may be flipped; represent orientation with (a, b).
    def search(remaining, chain, right):
        if not remaining:
            if chain[0][0] == right:
                return chain
            return None
        for i, (a, b) in enumerate(remaining):
            for left, end in ((a, b), (b, a)):
                if left == right:
                    rest = remaining[:i] + remaining[i + 1:]
                    result = search(rest, chain + [(left, end)], end)
                    if result is not None:
                        return result
        return None

    first = dominoes[0]
    return search(dominoes[1:], [first], first[1])
